# Circuitous Route (FDN): "Search your library for up to two basic land cards and/or Gate cards,
# put them onto the battlefield tapped, then shuffle."
# M21 Fabled Passage's SEARCH to the battlefield tapped + SHUFFLE, with "up to two" as QAtMost(2)
# (Alpine Houndmaster's searched QAtMost), the filter "basic land card or Gate card" (an FOr: a
# card may be either, "and/or"). SEARCH carries no `controller` role (MAPPER_GUIDE).
abilities = [
    SpellAbility(
        kind=SpellKind.SORCERY,
        effect=Seq(
            steps=(
                A(Verb.SEARCH, {
                    'cards': Selector(
                        count=QAtMost(n=2),
                        mode=SelectorMode.CHOOSE,
                        filter=FOr(
                            children=(
                                FAnd(
                                    children=(
                                        FAtom(pred=FAtomPred.SUPERTYPE_EQ, string_value='Basic'),
                                        FAtom(pred=FAtomPred.TYPE_EQ, string_value='Land'),
                                    ),
                                ),
                                FAtom(pred=FAtomPred.SUBTYPE_EQ, string_value='Gate'),
                            ),
                        ),
                        zones=(Zone(kind=ZoneKind.LIBRARY, controller=ControllerRef.YOU),),
                    ),
                    'destination': Zone(kind=ZoneKind.BATTLEFIELD, controller=ControllerRef.YOU),
                    'tapped_on_enter': True,
                }),
                A(Verb.SHUFFLE, {'zone': Zone(kind=ZoneKind.LIBRARY, controller=ControllerRef.YOU)}),
            ),
        ),
    ),
]
